-- +goose Up
-- Widen the search-only card index beyond Chase. Identity only: names and
-- networks read from each issuer's public card list on 2026-09-26, with no
-- rates or fees, so a chosen card is scored only after the cardholder supplies
-- terms. American Express and Bank of America pages could not be read
-- automatically and are deliberately not filled in from memory.
ON CONFLICT DO NOTHING;

-- +goose Down
DELETE FROM revocred.card_reference_index
WHERE terms_status = 'partial' AND source_captured_on = DATE '2026-09-26' AND issuer <> 'Chase';
